import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract_packages(data):
    result = {}
    for project in data.get('projects', []):
        name = project['path'].split('/')[-1]
        pkgs = {}
        for fw in project.get('frameworks', []):
            tf = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], tf)
                pkgs[key] = pkg['resolvedVersion']
        result[name] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)

print('=== VERSION CHANGES ===')
changes = False
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes = True
            print(f'  {proj}: {key[0]} ({key[1]}): {bv} -> {av}')

if not changes:
    print('  (none)')

print()
print('=== UNCHANGED (sample) ===')
count = 0
for proj in sorted(b.keys()):
    for key in sorted(b.get(proj, {}).keys()):
        if b[proj][key] == a.get(proj, {}).get(key):
            if count < 5:
                print(f'  {proj}: {key[0]} ({key[1]}): {b[proj][key]}')
            count += 1
print(f'  ... and {count - 5} more unchanged') if count > 5 else None
"

